function defenceItems(u, ph, opts){
  const out = [];
  // a Feel No Pain only one model has (Robotic Bodyguard: the Datasmith, not the robots) is said by that ability's own line
  // an army rule of the unit's Rules line can say it with its condition (def: Aegis of the Emperor, "Feel No Pain 5+ against mortal
  // wounds"); New Recruit's starred "Feel No Pain 5+*" is that one, so it is not said again without its condition
  const fac = factionOf(army()) || {}, armyDefs = (fac.armyRules || []).filter(r => r.def && hasRule(u, r.name));
  for(const r of u.rules){ const m = /^feel no pain (\d\+)/i.exec(r); if(m && !u.abilities.some(ab => ab.def && ab.def.includes('Feel No Pain ' + m[1])) && !(/\*$/.test(r) && armyDefs.some(x => x.def.includes('Feel No Pain ' + m[1])))) out.push({ t:'Feel No Pain ' + m[1], a:'rule', v:r, who:partialWho(u, r) || undefined }); }   // (who: the one model that has it, partialRules)
  for(const r of armyDefs) if(!(ph && r.defPh && !r.defPh.includes(ph))) out.push({ t:r.def, a:'rule', v:r.name });   // (defPh: Kaptaris, the Fight phase only)
  for(const r of unitDetRules(u)) if(r.def && !out.some(x => x.t === r.def)) out.push({ t:r.def, a:'rule', v:r.name });   // e.g. Knights of Legend: FNP 6+
  for(const { rule, part } of unitDetParts(u)) if(part.def) out.push({ t:part.def, a:'rule', v:rule.name });   // a part of it for some units (Boon of Blood)
  // (who, name: the model of an attached unit the ability is on, for the datasheet's line)
  for(const ab of u.abilities) if(ab.def && !naReason(ab) && !(ph && ab.defPh && !ab.defPh.includes(ph))) out.push({ t:ab.def, a:'ability', v:abilityKey(ab), who:ab.who, name:ab.name });
  for(const s of allStratagems()) if(s.def && eligible(s).includes(u) && !(ph && !s.phases.includes(ph))) out.push({ t:s.cp + 'CP ' + s.name + ': ' + s.def, a:'strat', v:s.id });
  if(opts && opts.shields) for(const s of allStratagems()) if(s.shield && s.shield.def && matches(s.shield.protects, u) && army().units.some(x => x !== u && matches(s.shield.by, x)) && !(ph && !s.phases.includes(ph)))
    out.push({ t:s.cp + 'CP ' + s.name + ': ' + s.shield.def, a:'strat', v:s.id });
  // and on the datasheet what another unit of the list gives this one when it is attacked (guard: Emanatus Forcefield,
  // Shroudpsalm, Necromechanic), as its attack auras show under its weapons; the source's name opens that unit
  // (one line for the same help from several units: the three Anathema Psykana units' Psychic Null)
  if(opts && opts.shields) for(const src of army().units) for(const g of src.guard || []) if(src !== u && matches(g.needs, u) && !out.some(x => x.guard && x.t === g.when + ': ' + g.note))
    out.push({ t:g.when + ': ' + g.note, a:'unit', v:src.id, guard:g });
  if(u.rules.includes('Waaagh!')) out.push({ t:'Riled up: 5+ INV', a:'rule', v:'Waaagh!', riled:true });
  return out;
}

function matches(n, u){
  if(!n) return true;
  if(n.all && !n.all.every(k => hasKw(u, k))) return false;
  if(n.any && !n.any.some(k => hasKw(u, k))) return false;
  if(n.none && n.none.some(k => hasKw(u, k))) return false;
  if(n.unless && matches(n.unless, u)) return false;
  // rule: the unit's Rules line names one of these rules (a Chaos Knight's Super-Heavy Walker, or a Preyslayer's Mantle bearer's)
  if(n.rule && !n.rule.some(r => hasRule(u, r))) return false;
  if(n.attached && !u.leads) return false;   // "a friendly attached … unit": one with a leader or support character
  return true;
}
